list.Add(new ArraySegment<byte>(lTxBytes));
list.Add(new ArraySegment<byte>(Encoding.ASCII.GetBytes(lTx.Identity)));
list.Add(new ArraySegment<byte>(Encoding.ASCII.GetBytes(lResponse)));
e.BufferList = list;

Bu davranış neredeyse hiç dokümante edilmemiştir ve ancak BufferList setter koduna detaylıca bakarsanız anlaşılabilir. Arka planda SocketAsyncEventArgs içinde, BufferList set edildiğinde byte dizisi referanslarını kopyalayan ve pinleyen, WSABuffer adlı bir array alanı (native kodla birlikte çalışmak için) bulunur. Native koda gönderilen asıl şey bu WSABuffer[] olduğu için, kodunuzun neden exception fırlattığı da buradan anlaşılmış olur.

